#include <stdio.h>
#include <string.h>



int main(void) {
    char a[202], b[102];
    fgets(a, 102, stdin); fgets(b, sizeof(b), stdin);
    a[strcspn(a, "\n")] = '\0'; b[strcspn(b, "\n")] = '\0';
    int i = 0, j = 0;
    while (a[i]) i++;
    do { a[i++] = b[j]; } while (b[j++]);
    puts(a);
    return 0;
}
